  string offline=Setup.Arg("--package-dir");if(offline!=null){File.Copy(Path.Combine(offline,(string)a["name"]),temp);Report(phase,(before+size)/total);}else{
   var uri=new Uri((string)a["url"]);using(var handler=new HttpClientHandler{AllowAutoRedirect=false})using(var client=new HttpClient(handler))using(var timeout=CancellationTokenSource.CreateLinkedTokenSource(stop.Token)){timeout.CancelAfter(TimeSpan.FromMinutes(10));client.Timeout=TimeSpan.FromMinutes(10);HttpResponseMessage response=null;try{for(int i=0;i<8;i++){if(uri.Scheme!="https")throw new Exception("HTTPS required");response=await client.GetAsync(uri,HttpCompletionOption.ResponseHeadersRead,timeout.Token);if((int)response.StatusCode<300||(int)response.StatusCode>=400)break;var next=response.Headers.Location;if(next==null)throw new Exception("Missing redirect");uri=next.IsAbsoluteUri?next:new Uri(uri,next);response.Dispose();response=null;}if(response==null||response.StatusCode!=HttpStatusCode.OK)throw new Exception("下载暂不可用 / Download unavailable");using(var input=await response.Content.ReadAsStreamAsync())using(var output=File.Create(temp)){byte[] b=new byte[65536];long read=0;int count;while((count=await input.ReadAsync(b,0,b.Length,timeout.Token))>0){read+=count;if(read>size)throw new Exception("Unexpected file size");await output.WriteAsync(b,0,count,timeout.Token);Report(phase,(before+read)/total);}}}finally{if(response!=null)response.Dispose();}}
  }Check();if(!Setup.Valid(temp,a))throw new Exception("下载校验失败 / Download verification failed");if(File.Exists(path))File.Replace(temp,path,null);else File.Move(temp,path);return path;
 }finally{if(File.Exists(temp))File.Delete(temp);}}
