 IEnumerable<Control> Descendants(Control parent){foreach(Control c in parent.Controls){yield return c;foreach(var child in Descendants(c))yield return child;}}
 void WriteVisualReport(string destination){string probe=(string)Visual.Appearance["glyphProbe"];var fonts=new[]{Visual.Font(12),Visual.Font(12,FontStyle.Bold)};var labels=Descendants(this).Where(c=>c is Label||c is PathDisplay).Select(c=>new {text=c.Text,font=c.Font.Name,size=c.Font.Size,covered=Visual.Covered(c.Font,c.Text),frame=new[]{PointToClient(c.PointToScreen(Point.Empty)).X,PointToClient(c.PointToScreen(Point.Empty)).Y,c.Width,c.Height}}).ToArray();var result=new{platform="Windows",language=zh?"zh":"en",state=Setup.Arg("--preview-state")??"idle",fonts=fonts.Select(f=>new{name=f.Name,probe=probe,covered=Visual.Covered(f,probe)}).ToArray(),labels=labels,width=ClientSize.Width,height=ClientSize.Height};File.WriteAllText(destination,new System.Web.Script.Serialization.JavaScriptSerializer().Serialize(result));foreach(var font in fonts)font.Dispose();}
 void UpdateProgress(string phase,double value){int index=phase.StartsWith("plugin")?0:phase.StartsWith("runtime")?1:2;if(new[]{"plugin","runtime","voices"}.Contains(phase)){bars[index].Value=value;var a=index==0?(Dictionary<string,object>)Setup.Config["plugin"]:Setup.Packages[index==1?1:0];double total=Convert.ToDouble(a["bytes"]);badges[index].Text=string.Format("{0:F0}%",value*100);details[index].Text=T("下载中","Downloading")+string.Format(" · {0:F1} / {1:F1} MB",value*total/1e6,total/1e6);status.Text=T("下载完成后将校验文件并配置声音。","Files are verified before voice setup.");}else if(phase.EndsWith("Done")){bars[index].Value=1;bars[index].Tint=Visual.Green;badges[index].Text=T("✓ 已下载","✓ Ready");details[index].Text=T("文件已校验","Download verified");}else if(phase.EndsWith("Extract")){details[index].Text=T("正在解压…","Unpacking…");}else if(phase=="verify"){status.Text=T("正在检查声音文件…","Checking voice files…")+string.Format(" {0:F0}%",value*100);}else if(phase=="reused"){for(int i=1;i<3;i++){bars[i].Value=1;bars[i].Tint=Visual.Green;badges[i].Text=T("✓ 已有","✓ Found");details[i].Text=T("已校验，跳过下载","Verified · No download needed");}}else if(phase=="setup"){cancel.Enabled=false;status.Text=T("正在验证声音可用性并完成安装…","Checking voices and finishing setup…");}else if(phase=="ready"){for(int i=1;i<3;i++){badges[i].Text=T("✓ 已就绪","✓ Ready");details[i].Text=T("声音已安装，可以离线听读","Installed · Ready for offline listening");}}}
 void PreparePlugin(){zoteroApp=ZoteroInstall.Applications().FirstOrDefault();var profiles=ZoteroInstall.Profiles(ZoteroInstall.ProfileBase);zoteroProfile=profiles.Count==1?profiles[0]:null;RefreshPluginUI();if(zoteroApp!=null&&zoteroProfile!=null)ContinuePlugin();pluginTimer=new System.Windows.Forms.Timer{Interval=1000};pluginTimer.Tick+=(s,e)=>{if(!complete)return;if(!didStage){if(zoteroApp==null)zoteroApp=ZoteroInstall.Applications().FirstOrDefault();if(zoteroProfile==null){var profilesNow=ZoteroInstall.Profiles(ZoteroInstall.ProfileBase);if(profilesNow.Count==1)zoteroProfile=profilesNow[0];}}if(pluginState=="running"&&!ZoteroInstall.Running())ContinuePlugin();if(didStage&&zoteroProfile!=null){var asset=(Dictionary<string,object>)Setup.Config["plugin"];pluginState=ZoteroInstall.Status(zoteroProfile.Path,(string)Setup.Config["version"],(string)asset["sha256"]);RefreshPluginUI();}};pluginTimer.Start();}
 void RefreshPluginUI(){target.Text="Zotero";path.Text=zoteroProfile!=null?zoteroProfile.Name:T("选择用户配置","Select a profile");browse.Text=T("选择配置","Profile");only.Text=T("手动安装","Manual install");if(zoteroApp==null){action.Text=T("选择 Zotero","Locate Zotero");status.Text=T("未找到 Zotero 10。请选择应用，或先安装并打开一次。","Zotero 10 not found. Locate it, or install and open it once.");return;}if(zoteroProfile==null){action.Text=T("选择配置","Select profile");status.Text=T("请选择要安装的用户配置；首次使用请先打开 Zotero 一次。","Choose a profile. First-time users: open Zotero once.");return;}action.Text=didStage?T("打开 Zotero","Open Zotero"):T("继续安装","Continue install");if(pluginState=="installed"){badges[0].Text=T("✓ 已安装","✓ Installed");details[0].Text=T("插件已启用，可以使用","Plugin enabled and ready");status.Text=T("安装完成。打开 Zotero 即可开始听读。","Setup complete. Open Zotero to start listening.");}else if(didStage){badges[0].Text=T("待启用","Enable in Zotero");details[0].Text=T("已放置并校验插件","Plugin placed and verified");status.Text=pluginState=="incompatible"?T("Zotero 暂不能启用此版本，请检查兼容性。","Zotero cannot enable this version. Check compatibility."):T("打开 Zotero → 工具 → 插件，启用 Paper Voice。","Open Zotero → Tools → Plugins. Enable Paper Voice.");}else if(pluginState=="running"){status.Text=T("请先正常退出 Zotero，安装器会自动继续。","Quit Zotero normally. Setup will continue automatically.");}else if(pluginState!="error"){status.Text=T("将安装到所选配置；已有设置会保留。","Install into this profile. Existing settings are kept.");}}
 void ChooseProfile(){var profiles=ZoteroInstall.Profiles(ZoteroInstall.ProfileBase);if(profiles.Count>1){using(var dialog=new Form{Text=T("选择 Zotero 配置","Choose a Zotero profile"),ClientSize=new Size(500,156),FormBorderStyle=FormBorderStyle.FixedDialog,StartPosition=FormStartPosition.CenterParent,MinimizeBox=false,MaximizeBox=false,BackColor=Visual.Paper,Font=Visual.Font(12)}){var label=new SmoothLabel{Text=T("仅安装到所选配置，其他配置保持不变。","Only the selected profile will receive the plugin."),Location=new Point(20,16),Size=new Size(460,26),ForeColor=Visual.Ink,UseCompatibleTextRendering=true};var select=new ComboBox{DropDownStyle=ComboBoxStyle.DropDownList,Location=new Point(20,48),Size=new Size(460,30),Font=Visual.Font(12)};select.Items.AddRange(profiles.Cast<object>().ToArray());select.SelectedIndex=0;var choose=new QuietButton{Text=T("选择","Choose"),Location=new Point(374,105),Size=new Size(106,34),BackColor=accent,ForeColor=Color.White,DialogResult=DialogResult.OK};var other=new QuietButton{Text=T("其他位置…","Browse…"),Location=new Point(254,105),Size=new Size(110,34),BackColor=Color.White,DialogResult=DialogResult.Retry};var cancelChoice=new QuietButton{Text=T("取消","Cancel"),Location=new Point(20,105),Size=new Size(80,34),BackColor=Color.White,DialogResult=DialogResult.Cancel};dialog.Controls.AddRange(new Control[]{label,select,choose,other,cancelChoice});dialog.AcceptButton=choose;dialog.CancelButton=cancelChoice;var result=dialog.ShowDialog(this);if(result==DialogResult.OK)zoteroProfile=(ZoteroProfile)select.SelectedItem;else if(result==DialogResult.Retry){if(!PickProfile())return;}else return;}}else if(!PickProfile())return;didStage=false;pluginState="";RefreshPluginUI();if(zoteroApp!=null)ContinuePlugin();}
 bool PickProfile(){using(var picker=new FolderBrowserDialog{Description=T("选择含 prefs.js 的 Zotero 配置目录","Choose a Zotero profile containing prefs.js"),SelectedPath=ZoteroInstall.ProfileBase,ShowNewFolderButton=false}){if(picker.ShowDialog(this)==DialogResult.OK){if(ZoteroInstall.ValidProfile(picker.SelectedPath)){zoteroProfile=new ZoteroProfile(Path.GetFileName(picker.SelectedPath),picker.SelectedPath);return true;}else status.Text=T("这不是 Zotero 配置目录。请选择含 prefs.js 的目录。","Choose a Zotero profile containing prefs.js.");}}return false;}
 void ContinuePlugin(){if(zoteroApp==null){using(var picker=new OpenFileDialog{Title=T("选择 Zotero 10","Locate Zotero 10"),Filter="Zotero|zotero.exe",CheckFileExists=true}){if(picker.ShowDialog(this)==DialogResult.OK&&ZoteroInstall.ValidApp(picker.FileName))zoteroApp=picker.FileName;}RefreshPluginUI();if(zoteroApp!=null&&zoteroProfile!=null)ContinuePlugin();return;}if(zoteroProfile==null){ChooseProfile();return;}if(didStage){try{if(!ZoteroInstall.Running())ZoteroInstall.Launch(zoteroApp,zoteroProfile.Path);else status.Text=T("请在 Zotero → 工具 → 插件中启用 Paper Voice。","Enable Paper Voice in Zotero → Tools → Plugins.");}catch(Exception e){status.Text=e.Message;}return;}if(ZoteroInstall.Running()){pluginState="running";RefreshPluginUI();return;}if(xpi==null)return;try{var asset=(Dictionary<string,object>)Setup.Config["plugin"];pluginState=ZoteroInstall.Stage(xpi,zoteroProfile.Path,(string)Setup.Config["version"],(string)asset["sha256"],Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"PaperVoiceInstaller","plugin-backups"));didStage=true;RefreshPluginUI();}catch(Exception e){pluginState="error";RefreshPluginUI();status.Text=e.Message;}}
 void Busy(bool value){busy=value;action.Enabled=only.Enabled=browse.Enabled=language.Enabled=!value;cancel.Visible=value;only.Visible=!value;cancel.Enabled=true;}
 async void Start(bool pluginOnly){Busy(true);complete=false;didStage=false;pluginState="";if(pluginTimer!=null)pluginTimer.Stop();engine=new Engine();engine.Progress=(p,v)=>BeginInvoke(new Action(()=>UpdateProgress(p,v)));try{xpi=await Task.Run(()=>engine.Install(root,Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"PaperVoiceInstaller"),Setup.Pointer,pluginOnly));complete=true;PreparePlugin();}catch(Exception e){action.Text=T("重试","Retry");status.Text=engine.Cancelled?T("已取消。原有声音保留，可继续下载。","Cancelled. Existing voices kept; retry to continue."):T("未完成：","Not completed: ")+e.Message;}finally{Busy(false);engine.Dispose();engine=null;}}
}
